UPDATE Users
SET name = CONCAT(
        UPPER(SUBSTR(name, 1, 1)),
        LOWER(SUBSTR(name, 2))
    )
WHERE name IS NOT NULL;

SELECT ROUND(100.0 * SUM(CASE WHEN Gender = 'Female' THEN 1 ELSE 0 END) / COUNT(*), 2) AS 'Female_Percentage_Sydney(%)'
FROM Vaccinations
WHERE City = 'Sydney';

SELECT DISTINCT HomeTeam, AVG(HomeAttendance) AS Avg_Home_Attendance, AwayTeam, AVG(AwayAttendance) AS Avg_Away_Attendance
FROM TeamStats
GROUP BY HomeTeam , AwayTeam ;

SELECT SUM(tickets_sold) AS num_tickets_sold 
FROM events 
WHERE category = 'music' OR category = 'theater';

